// Auto-generated — do not edit manually. Run: node build.js
module.exports = {
  "html": "<!DOCTYPE html>\r\n<html lang=\"zh-TW\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>CVE Web Scanner — NIST NVD</title>\r\n<style>\r\n*{box-sizing:border-box;margin:0;padding:0}\r\nbody{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#f1f5f9;color:#1e293b;line-height:1.55;min-height:100vh}\r\na{color:#2563eb;text-decoration:none}a:hover{text-decoration:underline}\r\n\r\nheader{background:linear-gradient(135deg,#1e3a5f 0%,#1e40af 100%);color:#fff;padding:28px 32px}\r\nheader h1{font-size:1.55rem;font-weight:800;margin-bottom:4px;letter-spacing:-.02em}\r\nheader p{font-size:.87rem;opacity:.7;margin-top:4px}\r\n\r\nmain{max-width:860px;margin:24px auto;padding:0 16px 40px}\r\n\r\n.card{background:#fff;border-radius:12px;padding:22px 26px;margin-bottom:18px;box-shadow:0 1px 4px rgba(0,0,0,.08)}\r\n.card-title{font-size:.93rem;font-weight:700;color:#1e3a5f;margin-bottom:16px;display:flex;align-items:center;gap:9px}\r\n.step-badge{background:#1e3a5f;color:#fff;width:22px;height:22px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:.68rem;font-weight:800;flex-shrink:0}\r\n\r\n/* Drop zone */\r\n#drop-zone{border:2px dashed #cbd5e1;border-radius:10px;padding:34px 20px;text-align:center;cursor:pointer;transition:all .18s;background:#f8fafc;user-select:none}\r\n#drop-zone:hover,#drop-zone.drag-over{border-color:#2563eb;background:#eff6ff}\r\n#drop-zone.has-file{border-color:#16a34a;background:#f0fdf4;cursor:default}\r\n.dz-icon{font-size:2rem;display:block;margin-bottom:8px;pointer-events:none}\r\n.dz-label{font-size:.9rem;color:#475569;font-weight:500;pointer-events:none}\r\n.dz-sub{font-size:.77rem;color:#94a3b8;margin-top:4px;pointer-events:none}\r\n#file-input{display:none}\r\n\r\n#file-info{display:none;margin-top:11px;font-size:.82rem;color:#475569;background:#f8fafc;border-radius:7px;padding:9px 13px;border-left:3px solid #16a34a}\r\n#file-info strong{color:#1e293b}\r\n\r\n/* Settings */\r\n.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}\r\n@media(max-width:580px){.settings-grid{grid-template-columns:1fr}}\r\n.form-group{display:flex;flex-direction:column;gap:4px}\r\n.form-group label{font-size:.74rem;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:.05em}\r\n.form-group input,.form-group select{border:1px solid #e2e8f0;border-radius:7px;padding:8px 10px;font-size:.87rem;color:#1e293b;outline:none;transition:border-color .15s,box-shadow .15s;background:#fff;width:100%}\r\n.form-group input:focus,.form-group select:focus{border-color:#2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.1)}\r\n.form-group .hint{font-size:.71rem;color:#94a3b8;margin-top:2px}\r\n.full-width{grid-column:1/-1}\r\n\r\n/* Actions */\r\n#action-card{display:flex;align-items:center;gap:12px;flex-wrap:wrap}\r\n#scan-btn{background:#1e3a5f;color:#fff;border:none;border-radius:8px;padding:11px 28px;font-size:.93rem;font-weight:700;cursor:pointer;transition:background .15s;white-space:nowrap}\r\n#scan-btn:hover:not(:disabled){background:#1e40af}\r\n#scan-btn:disabled{background:#94a3b8;cursor:not-allowed}\r\n#cancel-btn{background:transparent;color:#dc2626;border:1.5px solid #dc2626;border-radius:8px;padding:10px 18px;font-size:.87rem;font-weight:600;cursor:pointer;display:none;transition:all .15s}\r\n#cancel-btn:hover:not(:disabled){background:#fef2f2}\r\n#cancel-btn:disabled{opacity:.5;cursor:not-allowed}\r\n#scan-status{font-size:.83rem;color:#64748b}\r\n\r\n/* Progress & Result (nested inside tab panels) */\r\n.inner-section{border-top:1px solid #e2e8f0;margin-top:22px;padding-top:20px}\r\n.progress-bar-wrap{background:#e2e8f0;border-radius:999px;height:7px;margin-bottom:11px;overflow:hidden}\r\n.progress-bar{height:100%;background:linear-gradient(90deg,#2563eb,#3b82f6);border-radius:999px;transition:width .4s ease;width:0}\r\n.progress-stats{font-size:.8rem;color:#64748b;margin-bottom:10px;display:flex;gap:16px;flex-wrap:wrap}\r\n.progress-stats strong{color:#1e293b}\r\n.progress-log{background:#0f172a;border-radius:9px;padding:14px 16px;font-family:'Cascadia Code','Fira Mono',Consolas,monospace;font-size:.76rem;color:#94a3b8;max-height:300px;overflow-y:auto;line-height:1.65;word-break:break-all}\r\n.l-ok{color:#4ade80}.l-warn{color:#fbbf24}.l-err{color:#f87171}.l-info{color:#60a5fa}.l-gray{color:#64748b}.l-b{font-weight:700;color:#e2e8f0}\r\n.progress-log a{color:#60a5fa;text-decoration:none}.progress-log a:hover{text-decoration:underline}\r\n.dl-row{display:flex;gap:10px;flex-wrap:wrap}\r\n.dl-btn{display:inline-flex;align-items:center;gap:8px;border-radius:8px;padding:11px 22px;font-size:.88rem;font-weight:700;text-decoration:none;transition:all .15s;cursor:pointer;border:none}\r\n.dl-btn.primary{background:#1e3a5f;color:#fff}\r\n.dl-btn.primary:hover{background:#1e40af;text-decoration:none;color:#fff}\r\n.dl-btn.secondary{background:#f1f5f9;color:#1e293b;border:1.5px solid #e2e8f0}\r\n.dl-btn.secondary:hover{background:#e2e8f0;text-decoration:none;color:#1e293b}\r\n\r\n/* Portable rows */\r\n#portable-list{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}\r\n.portable-row{display:flex;gap:8px;align-items:center}\r\n.portable-row input{border:1px solid #e2e8f0;border-radius:7px;padding:8px 10px;font-size:.87rem;color:#1e293b;outline:none;transition:border-color .15s,box-shadow .15s;background:#fff}\r\n.portable-row input:focus{border-color:#2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.1)}\r\n.pt-name{flex:3}.pt-ver{flex:1.5}\r\n.pt-del{flex:none;background:none;border:1px solid #e2e8f0;border-radius:6px;padding:7px 11px;cursor:pointer;color:#94a3b8;font-size:.85rem;line-height:1;transition:all .15s}\r\n.pt-del:hover{background:#fef2f2;border-color:#fca5a5;color:#ef4444}\r\n#add-portable-btn{background:none;border:1.5px dashed #cbd5e1;border-radius:7px;padding:8px 16px;color:#64748b;cursor:pointer;font-size:.83rem;width:100%;transition:all .15s;margin-top:2px}\r\n#add-portable-btn:hover{border-color:#2563eb;color:#2563eb;background:#eff6ff}\r\n\r\n/* Tabs */\r\n.tab-bar{display:flex;gap:0;margin-bottom:-1px;position:relative;z-index:1;padding-left:1px}\r\n.tab-btn{background:#f8fafc;border:1px solid #e2e8f0;border-bottom:none;border-radius:10px 10px 0 0;padding:10px 22px;font-size:.88rem;font-weight:600;color:#64748b;cursor:pointer;margin-right:4px;transition:background .15s,color .15s;white-space:nowrap}\r\n.tab-btn:hover:not(.active){background:#eff6ff;color:#2563eb;border-color:#bfdbfe}\r\n.tab-btn.active{background:#fff;color:#1e3a5f}\r\n.tab-bar-bottom{margin-top:12px;padding-left:1px}\r\n.tab-bar-bottom .tab-btn{border-bottom:1px solid #e2e8f0;border-radius:0 0 10px 10px}\r\n.tab-panel{display:none;background:#fff;border:1px solid #e2e8f0;border-radius:0 12px 12px 12px;padding:22px 26px;margin-bottom:18px;box-shadow:0 1px 4px rgba(0,0,0,.08)}\r\n.tab-panel.active{display:block}\r\n.section-divider{border:none;border-top:1px solid #f1f5f9;margin:18px -26px}\r\n.tab-hint{font-size:.78rem;color:#64748b;margin-bottom:14px;line-height:1.5}\r\n/* Manual entry rows */\r\n#manual-list{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}\r\n.manual-row{display:flex;gap:8px;align-items:center}\r\n.manual-row input{border:1px solid #e2e8f0;border-radius:7px;padding:8px 10px;font-size:.87rem;color:#1e293b;outline:none;transition:border-color .15s,box-shadow .15s;background:#fff}\r\n.manual-row input:focus{border-color:#2563eb;box-shadow:0 0 0 3px rgba(37,99,235,.1)}\r\n.mn-name{flex:3}.mn-ver{flex:1.5}\r\n.mn-del{flex:none;background:none;border:1px solid #e2e8f0;border-radius:6px;padding:7px 11px;cursor:pointer;color:#94a3b8;font-size:.85rem;line-height:1;transition:all .15s}\r\n.mn-del:hover{background:#fef2f2;border-color:#fca5a5;color:#ef4444}\r\n#add-manual-btn{background:none;border:1.5px dashed #cbd5e1;border-radius:7px;padding:8px 16px;color:#64748b;cursor:pointer;font-size:.83rem;width:100%;transition:all .15s;margin-top:2px}\r\n#add-manual-btn:hover{border-color:#2563eb;color:#2563eb;background:#eff6ff}\r\n\r\nfooter{text-align:center;padding:24px;font-size:.74rem;color:#94a3b8}\r\n</style>\r\n</head>\r\n<body>\r\n\r\n<header>\r\n  <h1>CVE Web Scanner</h1>\r\n  <p>上傳 scan.json &rarr; 查詢 NIST NVD CVE API &rarr; 檢視弱點報表 &nbsp;·&nbsp; 無需安裝 Node.js，零伺服器</p>\r\n</header>\r\n\r\n<main>\r\n\r\n<!-- Settings (shared: API key, severity, year, max CVEs) -->\r\n<div class=\"card\">\r\n  <div class=\"card-title\">⚙ 掃描設定（選填，設定會自動儲存）</div>\r\n  <div class=\"settings-grid\">\r\n    <div class=\"form-group\">\r\n      <label>NIST API Key</label>\r\n      <input type=\"password\" id=\"api-key\" placeholder=\"未填仍可運作，但速率較慢\">\r\n      <span class=\"hint\">無 Key：6.5 秒/次 &nbsp;|&nbsp; 有 Key：0.7 秒/次 &nbsp;&nbsp;<a href=\"https://nvd.nist.gov/developers/request-an-api-key\" target=\"_blank\">免費申請</a></span>\r\n    </div>\r\n    <div class=\"form-group\">\r\n      <label>最低嚴重度</label>\r\n      <select id=\"min-severity\">\r\n        <option value=\"LOW\">LOW（全部）</option>\r\n        <option value=\"MEDIUM\">MEDIUM</option>\r\n        <option value=\"HIGH\" selected>HIGH（預設）</option>\r\n        <option value=\"CRITICAL\">CRITICAL（僅最高）</option>\r\n      </select>\r\n    </div>\r\n    <div class=\"form-group\">\r\n      <label>CVE 最早年份</label>\r\n      <input type=\"number\" id=\"min-year\" placeholder=\"空白=當年−5（預設）\">\r\n      <span class=\"hint\">只顯示該年份後發佈的 CVE</span>\r\n    </div>\r\n    <div class=\"form-group\">\r\n      <label>每項軟體最多 CVE 筆數</label>\r\n      <input type=\"number\" id=\"max-cves\" value=\"50\" min=\"1\" max=\"2000\">\r\n      <span class=\"hint\">NVD 回傳順序為最新優先</span>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- Tab navigation -->\r\n<div class=\"tab-bar\">\r\n  <button class=\"tab-btn active\" data-tab=\"file\">📁 檔案掃描(JSON)</button>\r\n  <button class=\"tab-btn\" data-tab=\"manual\">✏ 人工掃描</button>\r\n</div>\r\n\r\n<!-- Tab: File mode -->\r\n<div class=\"tab-panel active\" id=\"tab-file\">\r\n  <div class=\"card-title\"><span class=\"step-badge\">1</span> 上傳 scan.json</div>\r\n  <div id=\"drop-zone\">\r\n    <span class=\"dz-icon\">📂</span>\r\n    <div class=\"dz-label\">點擊選擇檔案，或將 scan.json 拖曳至此</div>\r\n    <div class=\"dz-sub\">由 cve-checker.js 或 findSW.ps1 在目標機器上產生的 JSON 掃描檔</div>\r\n  </div>\r\n  <input type=\"file\" id=\"file-input\" accept=\".json,application/json\">\r\n  <div id=\"file-info\"></div>\r\n  <div id=\"findsw-dl-hint\" style=\"display:none;margin-top:10px;font-size:.8rem;color:#64748b;background:#f8fafc;border-radius:7px;padding:9px 13px;border-left:3px solid #2563eb\">\r\n    還沒有 scan.json？先在目標 Windows 機器上執行 <strong>findSW.ps1</strong> 產生掃描檔，再上傳至此。\r\n    &nbsp;<span style=\"color:#64748b\">（請向系統維護人員索取 PS1 檔案掃描工具）</span>\r\n  </div>\r\n  <hr class=\"section-divider\">\r\n  <div class=\"card-title\" style=\"margin-top:4px\"><span class=\"step-badge\">2</span> 白名單（Publisher 關鍵字，逗號分隔）</div>\r\n  <div class=\"form-group\" style=\"margin-bottom:0\">\r\n    <input type=\"text\" id=\"whitelist\" placeholder=\"例：Microsoft,Apple,Google\">\r\n    <span class=\"hint\">不分大小寫，部分比對 Publisher 欄位；符合條件的軟體略過掃描</span>\r\n  </div>\r\n  <div id=\"portable-section\">\r\n  <hr class=\"section-divider\">\r\n  <div class=\"card-title\" style=\"margin-top:4px\"><span class=\"step-badge\">3</span> 免安裝軟體（Portable / 未登錄於 Registry）</div>\r\n  <div id=\"portable-list\"></div>\r\n  <button type=\"button\" id=\"add-portable-btn\">＋ 新增項目</button>\r\n  <p class=\"form-group\" style=\"margin-top:8px\"><span class=\"hint\">不受白名單過濾，直接納入掃描。版本號可選填，用於比對是否需要升級。</span></p>\r\n  </div>\r\n  <!-- File scan: progress & result -->\r\n  <div class=\"inner-section\" id=\"file-progress-card\" style=\"display:none\">\r\n    <div class=\"card-title\">掃描進度</div>\r\n    <div class=\"progress-bar-wrap\"><div class=\"progress-bar\" id=\"file-progress-bar\"></div></div>\r\n    <div class=\"progress-stats\" id=\"file-progress-stats\"></div>\r\n    <div class=\"progress-log\" id=\"file-progress-log\"></div>\r\n  </div>\r\n  <div class=\"inner-section\" id=\"file-result-card\" style=\"display:none\">\r\n    <div class=\"card-title\">✅ 掃描完成</div>\r\n    <div class=\"dl-row\">\r\n      <button id=\"file-open-report-btn\" class=\"dl-btn primary\">📄 在新分頁開啟報表</button>\r\n      <a id=\"file-dl-html\" class=\"dl-btn secondary\" download=\"result.html\">⬇ 下載報表 HTML</a>\r\n      <a id=\"file-dl-json\" class=\"dl-btn secondary\" download=\"result.json\">⬇ result.json</a>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- Tab: Manual entry mode -->\r\n<div class=\"tab-panel\" id=\"tab-manual\">\r\n  <p class=\"tab-hint\">直接輸入軟體名稱與版本號，不需要 scan.json 檔案。版本號可選填，留空仍可查詢 CVE，但無法判斷是否需要升級。此模式不套用白名單過濾。</p>\r\n  <div id=\"manual-list\"></div>\r\n  <button type=\"button\" id=\"add-manual-btn\">＋ 新增軟體</button>\r\n  <!-- Manual scan: progress & result (no downloads) -->\r\n  <div class=\"inner-section\" id=\"manual-progress-card\" style=\"display:none\">\r\n    <div class=\"card-title\">掃描進度</div>\r\n    <div class=\"progress-bar-wrap\"><div class=\"progress-bar\" id=\"manual-progress-bar\"></div></div>\r\n    <div class=\"progress-stats\" id=\"manual-progress-stats\"></div>\r\n    <div class=\"progress-log\" id=\"manual-progress-log\"></div>\r\n  </div>\r\n  <div class=\"inner-section\" id=\"manual-result-card\" style=\"display:none\">\r\n    <div class=\"card-title\">✅ 掃描完成</div>\r\n    <div class=\"dl-row\">\r\n      <button id=\"manual-open-report-btn\" class=\"dl-btn primary\">📄 在新分頁開啟報表</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- Action -->\r\n<div class=\"card\" id=\"action-card\">\r\n  <button id=\"scan-btn\" disabled>▶ 開始掃描</button>\r\n  <button id=\"cancel-btn\">■ 取消掃描</button>\r\n  <span id=\"scan-status\">請先上傳 scan.json</span>\r\n</div>\r\n\r\n<!-- Bottom tab navigation -->\r\n<div class=\"tab-bar tab-bar-bottom\">\r\n  <button class=\"tab-btn active\" data-tab=\"file\">📁 檔案掃描(JSON)</button>\r\n  <button class=\"tab-btn\" data-tab=\"manual\">✏ 人工掃描</button>\r\n</div>\r\n\r\n</main>\r\n<footer>CVE Web Scanner &nbsp;·&nbsp; Powered by <a href=\"https://nvd.nist.gov/developers/vulnerabilities\" target=\"_blank\">NIST NVD API 2.0</a><br>This product uses data from the NVD API but is not endorsed or certified by the NVD.</footer>\r\n\r\n<script>\r\n'use strict';\r\n\r\n// ─── Constants ────────────────────────────────────────────────────────────────\r\nconst NVD_CVE_BASE = window.__NVD_PROXY__ || 'https://services.nvd.nist.gov/rest/json/cves/2.0';\r\nconst SEVERITY_ORDER = ['NONE', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];\r\n\r\nconst SKIP_PATTERNS = [\r\n    /^Microsoft Visual C\\+\\+.*(Additional|Minimum) Runtime/i,\r\n    /^Microsoft Visual C\\+\\+.*x(64|86) (Additional|Minimum)/i,\r\n    /^Office \\d+ Click-to-Run (Extensibility|Licensing|Localization)/i,\r\n    /^Python 3\\.\\d+\\.\\d+ (Add to Path|Core Interpreter|Development Libraries|Documentation|Executables|pip Bootstrap|Standard Library|Tcl\\/Tk|Test Suite|Utility Scripts)/i,\r\n    /^Microsoft Visual C\\+\\+ v14 Redistributable/i,\r\n];\r\n\r\n// ─── Module state ─────────────────────────────────────────────────────────────\r\nlet scanData = null;\r\nlet abortController = null;\r\nconst tabBlobUrls = { file: [], manual: [] };\r\nlet activeTab = 'file';\r\n\r\n// ─── HTML escaping ────────────────────────────────────────────────────────────\r\nfunction esc(s) {\r\n    return (s == null ? '' : String(s))\r\n        .replace(/&/g, '&amp;').replace(/</g, '&lt;')\r\n        .replace(/>/g, '&gt;').replace(/\"/g, '&quot;')\r\n        .replace(/'/g, '&#39;');\r\n}\r\n\r\n// ─── Core logic (ported from cve-checker.js) ─────────────────────────────────\r\nfunction shouldSkip(name) {\r\n    return SKIP_PATTERNS.some(p => p.test(name));\r\n}\r\n\r\nfunction formatDateTime(iso) {\r\n    const d = new Date(iso);\r\n    const pad = n => String(n).padStart(2, '0');\r\n    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;\r\n}\r\n\r\nfunction cleanProductName(name) {\r\n    return name\r\n        .replace(/\\s+\\d+[\\d.]*(\\.\\d+)*(\\s|$)/g, ' ')\r\n        .replace(/\\s*\\(.*?\\)\\s*/g, ' ')\r\n        .replace(/\\s+-\\s+[\\d.]+\\s*$/g, '')\r\n        .replace(/\\s+(x64|x86|32-bit|64-bit)(\\s|$)/gi, ' ')\r\n        .replace(/\\s+/g, ' ')\r\n        .trim();\r\n}\r\n\r\nfunction matchWhitelist(sw, whitelist) {\r\n    const publisher = (sw.publisher || '').toLowerCase();\r\n    for (const rule of whitelist) {\r\n        if (publisher.includes(rule.toLowerCase())) return rule;\r\n    }\r\n    return null;\r\n}\r\n\r\nfunction compareVersions(a, b) {\r\n    const parse = v => String(v).split('.').map(n => parseInt(n, 10) || 0);\r\n    const ap = parse(a), bp = parse(b);\r\n    const len = Math.max(ap.length, bp.length);\r\n    for (let i = 0; i < len; i++) {\r\n        const diff = (ap[i] || 0) - (bp[i] || 0);\r\n        if (diff !== 0) return diff;\r\n    }\r\n    return 0;\r\n}\r\n\r\nfunction isSafeVersion(installed, rec) {\r\n    if (!installed || !rec) return false;\r\n    const cmp = compareVersions(installed, rec.version);\r\n    return rec.op === '>=' ? cmp >= 0 : cmp > 0;\r\n}\r\n\r\nfunction getCvss(cve) {\r\n    const m = cve.metrics || {};\r\n    const checks = [\r\n        ['cvssMetricV40', '4.0'],\r\n        ['cvssMetricV31', '3.1'],\r\n        ['cvssMetricV30', '3.0'],\r\n        ['cvssMetricV2',  '2.0'],\r\n    ];\r\n    for (const [key, ver] of checks) {\r\n        if (m[key]?.[0]) {\r\n            const entry = m[key][0];\r\n            const d = entry.cvssData;\r\n            const severity = (d.baseSeverity || entry.baseSeverity || 'NONE').toUpperCase();\r\n            return { score: d.baseScore, severity, version: ver };\r\n        }\r\n    }\r\n    return { score: 0, severity: 'NONE', version: 'N/A' };\r\n}\r\n\r\nfunction cveRelevanceCheck(cve, searchName) {\r\n    const configs = cve.configurations || [];\r\n    if (!configs.length) return null;\r\n    const words = searchName.toLowerCase()\r\n        .replace(/[^a-z0-9]/g, ' ').split(/\\s+/).filter(w => w.length >= 2);\r\n    if (!words.length) return null;\r\n    const cpeLines = [];\r\n    for (const config of configs) {\r\n        for (const node of (config.nodes || [])) {\r\n            for (const m of (node.cpeMatch || [])) {\r\n                if (m.criteria) cpeLines.push(m.criteria.toLowerCase().replace(/[_:]/g, ' '));\r\n            }\r\n        }\r\n    }\r\n    if (!cpeLines.length) return null;\r\n    const cpeText = cpeLines.join(' ');\r\n    return words.every(w => cpeText.includes(w));\r\n}\r\n\r\nfunction findAllCPEBases(products, nameWords) {\r\n    if (!nameWords.length || !products.length) return [];\r\n    const results = [];\r\n    const seen = new Set();\r\n    const add = parts => {\r\n        const key = `${parts[3]}:${parts[4]}`;\r\n        if (seen.has(key)) return;\r\n        seen.add(key);\r\n        results.push({ vendor: parts[3], product: parts[4] });\r\n    };\r\n    // Pass 0: vendor alone contains all name words\r\n    for (const { cpe } of products) {\r\n        const parts = cpe.cpeName.split(':');\r\n        if (parts.length < 5 || parts[2] !== 'a') continue;\r\n        const vendor = parts[3].replace(/[_:.]/g, ' ').toLowerCase();\r\n        if (nameWords.every(w => vendor.includes(w))) add(parts);\r\n    }\r\n    // Pass 1: vendor+product combined contains all name words\r\n    for (const { cpe } of products) {\r\n        const parts = cpe.cpeName.split(':');\r\n        if (parts.length < 5 || parts[2] !== 'a') continue;\r\n        const cpeStr = `${parts[3]} ${parts[4]}`.replace(/[_:.]/g, ' ').toLowerCase();\r\n        if (nameWords.every(w => cpeStr.includes(w))) add(parts);\r\n    }\r\n    // Pass 2: fallback — first word in product (only if no results yet)\r\n    if (results.length === 0) {\r\n        const firstWord = nameWords[0];\r\n        for (const { cpe } of products) {\r\n            const parts = cpe.cpeName.split(':');\r\n            if (parts.length < 5 || parts[2] !== 'a') continue;\r\n            const product = parts[4].replace(/[_:.]/g, ' ').toLowerCase();\r\n            if (product.includes(firstWord)) add(parts);\r\n        }\r\n    }\r\n    return results;\r\n}\r\n\r\nfunction cveMatchesCPEBase(cve, bases) {\r\n    const patterns = bases.map(b => `:${b.vendor}:${b.product}:`.toLowerCase());\r\n    const configs = cve.configurations || [];\r\n    if (!configs.length) return null;\r\n    let hasCPEs = false;\r\n    for (const config of configs) {\r\n        for (const node of (config.nodes || [])) {\r\n            for (const m of (node.cpeMatch || [])) {\r\n                if (!m.criteria) continue;\r\n                hasCPEs = true;\r\n                const criteria = m.criteria.toLowerCase();\r\n                if (patterns.some(p => criteria.includes(p))) return true;\r\n            }\r\n        }\r\n    }\r\n    return hasCPEs ? false : null;\r\n}\r\n\r\nfunction extractFixedVersion(cve, searchName, cpeBase = null) {\r\n    let words;\r\n    if (cpeBase) {\r\n        const raw = `${cpeBase.vendor} ${cpeBase.product}`.replace(/_/g, ' ').toLowerCase();\r\n        words = [...new Set(raw.split(/\\s+/).filter(w => w.length >= 2))];\r\n    } else {\r\n        words = searchName\r\n            ? searchName.toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\\s+/).filter(w => w.length >= 2)\r\n            : [];\r\n    }\r\n    let best = null;\r\n    for (const config of (cve.configurations || [])) {\r\n        for (const node of (config.nodes || [])) {\r\n            for (const match of (node.cpeMatch || [])) {\r\n                if (!match.vulnerable) continue;\r\n                if (words.length && match.criteria) {\r\n                    const cpe = match.criteria.toLowerCase().replace(/[_:]/g, ' ');\r\n                    if (!words.every(w => cpe.includes(w))) continue;\r\n                }\r\n                let candidate = null;\r\n                if (match.versionEndExcluding) {\r\n                    candidate = { version: match.versionEndExcluding, op: '>=' };\r\n                } else if (match.versionEndIncluding) {\r\n                    candidate = { version: match.versionEndIncluding, op: '>' };\r\n                }\r\n                if (candidate && (!best || compareVersions(candidate.version, best.version) > 0)) {\r\n                    best = candidate;\r\n                }\r\n            }\r\n        }\r\n    }\r\n    return best;\r\n}\r\n\r\nfunction getRecommendedVersion(rawCves, searchName, cpeBase = null) {\r\n    // rawCves: full NVD API objects (with .cve nested property)\r\n    let best = null;\r\n    for (const v of rawCves) {\r\n        const fix = extractFixedVersion(v.cve, searchName, cpeBase);\r\n        if (fix && (!best || compareVersions(fix.version, best.version) > 0)) best = fix;\r\n    }\r\n    return best;\r\n}\r\n\r\n// Check if a CVE only lists exact affected versions (no ranges).\r\n// Returns null                          → has ranges or can't determine → skip\r\n// Returns { affected: true }            → installed version is in exact affected list\r\n// Returns { affected: false, versions } → not in list → CVE doesn't apply\r\nfunction cveExactVersionCheck(installedVersion, cve, searchName, cpeBase) {\r\n    let words;\r\n    if (cpeBase) {\r\n        const raw = `${cpeBase.vendor} ${cpeBase.product}`.replace(/_/g, ' ').toLowerCase();\r\n        words = [...new Set(raw.split(/\\s+/).filter(w => w.length >= 2))];\r\n    } else {\r\n        words = searchName\r\n            ? searchName.toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\\s+/).filter(w => w.length >= 2)\r\n            : [];\r\n    }\r\n\r\n    const matchingEntries = [];\r\n    for (const config of (cve.configurations || [])) {\r\n        for (const node of (config.nodes || [])) {\r\n            for (const match of (node.cpeMatch || [])) {\r\n                if (!match.vulnerable) continue;\r\n                if (words.length && match.criteria) {\r\n                    const cpe = match.criteria.toLowerCase().replace(/[_:]/g, ' ');\r\n                    if (!words.every(w => cpe.includes(w))) continue;\r\n                }\r\n                matchingEntries.push(match);\r\n            }\r\n        }\r\n    }\r\n\r\n    if (matchingEntries.length === 0) return null;\r\n\r\n    const hasRange = matchingEntries.some(m =>\r\n        m.versionEndExcluding || m.versionEndIncluding ||\r\n        m.versionStartIncluding || m.versionStartExcluding\r\n    );\r\n    if (hasRange) return null;\r\n\r\n    // CPE 2.3 format: cpe:2.3:a:vendor:product:VERSION:...\r\n    const affectedVersions = matchingEntries\r\n        .map(m => (m.criteria || '').split(':')[5] || '')\r\n        .filter(v => v && v !== '*' && v !== '-');\r\n\r\n    if (affectedVersions.length === 0) return null;\r\n    if (!installedVersion || installedVersion === '?') return null;\r\n\r\n    const isAffected = affectedVersions.some(v => compareVersions(installedVersion, v) === 0);\r\n    return isAffected ? { affected: true } : { affected: false, versions: affectedVersions };\r\n}\r\n\r\n// ─── Rate-limited fetch ───────────────────────────────────────────────────────\r\nfunction sleep(ms, signal) {\r\n    return new Promise((resolve, reject) => {\r\n        if (signal?.aborted) return reject(new DOMException('Aborted', 'AbortError'));\r\n        const timer = setTimeout(resolve, ms);\r\n        signal?.addEventListener('abort', () => { clearTimeout(timer); reject(new DOMException('Aborted', 'AbortError')); }, { once: true });\r\n    });\r\n}\r\n\r\nconst MAX_FETCH_RETRIES   = 10;   // total retry attempts per software item\r\nconst FETCH_RETRY_DELAY_MS = 5000; // ms between retries (except 429 rate-limit)\r\n\r\nasync function nvdFetch(url, apiKey, signal, retries = MAX_FETCH_RETRIES, onRetry = null) {\r\n    const headers = {};\r\n    // When proxied through local server, API key is added server-side to avoid CORS preflight\r\n    if (apiKey && !window.__NVD_PROXY__) headers['apiKey'] = apiKey;\r\n    const attempt = MAX_FETCH_RETRIES - retries + 1;\r\n    const delaySec = FETCH_RETRY_DELAY_MS / 1000;\r\n    let res;\r\n    try {\r\n        // 45 s per-request browser timeout: longer than proxy's 30 s NVD timeout so the\r\n        // proxy always responds first under normal conditions, but catches cases where the\r\n        // proxy hangs (e.g. 4 consecutive NVD timeouts = ~124 s wait without this guard).\r\n        const perReqSignal = typeof AbortSignal.any === 'function'\r\n            ? AbortSignal.any([signal, AbortSignal.timeout(45000)])\r\n            : signal;\r\n        res = await fetch(url, { headers, signal: perReqSignal });\r\n    } catch (err) {\r\n        if (err.name === 'AbortError' && signal.aborted) throw err; // user cancelled\r\n        // TimeoutError (45 s browser guard) or network error — retry\r\n        if (retries > 0) {\r\n            const isTimeout = err.name === 'TimeoutError' || (err.name === 'AbortError' && !signal.aborted);\r\n            onRetry?.(isTimeout\r\n                ? `請求逾時，${delaySec} 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`\r\n                : `連線失敗 [${err.name}]，${delaySec} 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`);\r\n            await sleep(FETCH_RETRY_DELAY_MS, signal);\r\n            return nvdFetch(url, apiKey, signal, retries - 1, onRetry);\r\n        }\r\n        throw err;\r\n    }\r\n    if (res.ok) {\r\n        try {\r\n            return await res.json();\r\n        } catch (_) {\r\n            // Truncated response (proxy lost NVD connection mid-stream) — retry\r\n            if (retries > 0) {\r\n                onRetry?.(`回應不完整，${delaySec} 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`);\r\n                await sleep(FETCH_RETRY_DELAY_MS, signal);\r\n                return nvdFetch(url, apiKey, signal, retries - 1, onRetry);\r\n            }\r\n            throw new Error('NVD API 回應不完整（連線中斷）');\r\n        }\r\n    }\r\n    if (res.status === 429 && retries > 0) {\r\n        onRetry?.(`速率限制 (429)，15 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`);\r\n        await sleep(15000, signal);\r\n        return nvdFetch(url, apiKey, signal, retries - 1, onRetry);\r\n    }\r\n    // 502/503/504 = proxy error or NVD timeout; 403 = NVD rejected — all worth one retry\r\n    if ((res.status === 502 || res.status === 503 || res.status === 504 || res.status === 403) && retries > 0) {\r\n        onRetry?.(`HTTP ${res.status}，${delaySec} 秒後重試 ${attempt}/${MAX_FETCH_RETRIES}…`);\r\n        await sleep(FETCH_RETRY_DELAY_MS, signal);\r\n        return nvdFetch(url, apiKey, signal, retries - 1, onRetry);\r\n    }\r\n    throw new Error(`NVD API HTTP ${res.status}`);\r\n}\r\n\r\nasync function searchCVEs(keyword, apiKey, maxCves, minYear, signal, onRetry) {\r\n    const params = new URLSearchParams({ keywordSearch: keyword, resultsPerPage: String(maxCves), noRejected: '' });\r\n    return nvdFetch(`${NVD_CVE_BASE}?${params}`, apiKey, signal, MAX_FETCH_RETRIES, onRetry);\r\n}\r\n\r\n// ─── HTML Report (matches cve-checker.js generateHTML output) ─────────────────\r\nfunction buildHTMLReport(report) {\r\n    const SEV_COLOR = { CRITICAL: '#dc2626', HIGH: '#ea580c', MEDIUM: '#d97706', LOW: '#2563eb' };\r\n    const badge = (sev, score) =>\r\n        `<span class=\"badge\" style=\"background:${SEV_COLOR[sev]||'#6b7280'}\">${esc(sev)}${score !== '' ? ' '+score : ''}</span>`;\r\n    const hasUnfixedCVE = r => (r.cves || []).some(v => !v.fixedVersion);\r\n    const needUpgrade = report.results.filter(r => r.recommendedVersion && !isSafeVersion(r.software.version, r.recommendedVersion)).length;\r\n    const alreadySafe = report.results.filter(r => r.recommendedVersion && isSafeVersion(r.software.version, r.recommendedVersion) && !hasUnfixedCVE(r)).length;\r\n    const cleanCount = (report.cleanResults || []).length;\r\n    const noRecCount = report.results.filter(r => !r.recommendedVersion || (isSafeVersion(r.software.version, r.recommendedVersion) && hasUnfixedCVE(r))).length;\r\n    const scanDateStr = (report.generatedAt || '').substring(0, 10).replace(/-/g, '/');\r\n    const minYearLabel = report.minYear ? `${report.minYear}/01/01~${scanDateStr}` : '不限';\r\n\r\n    // Whitelist section\r\n    const wlGroups = {};\r\n    for (const sw of (report.whitelisted || [])) (wlGroups[sw.matchedRule] ??= []).push(sw);\r\n    const wlHTML = (report.whitelisted || []).length === 0 ? '' : `\r\n  <section id=\"whitelisted\">\r\n    <h2>白名單跳過的軟體（${report.whitelisted.length} 筆，未進行掃描）</h2>\r\n    <p class=\"sec-note\">以下軟體因 Publisher 符合白名單設定而略過，未查詢 NIST NVD。</p>\r\n    ${Object.entries(wlGroups).map(([rule, list]) => `\r\n    <div class=\"wl-group\"><div class=\"wl-rule\">規則：${esc(rule)}</div>\r\n    <table><thead><tr><th>Software</th><th>Version</th><th>Publisher</th></tr></thead>\r\n    <tbody>${list.map(sw => `<tr><td>${esc(sw.name)}</td><td>${esc(sw.version)}</td><td>${esc(sw.publisher)}</td></tr>`).join('')}</tbody></table></div>`).join('')}\r\n  </section>`;\r\n\r\n    const patternHTML = (report.skippedByPattern || []).length === 0 ? '' : `\r\n  <section id=\"skipped-pattern\">\r\n    <h2>子元件跳過的軟體（${report.skippedByPattern.length} 筆，未進行掃描）</h2>\r\n    <p class=\"sec-note\">以下軟體符合內建 SKIP_PATTERNS 規則（VC++ Runtime 子元件、Office Click-to-Run 元件、Python 子安裝項），略過。</p>\r\n    <table><thead><tr><th>Software</th><th>Version</th><th>Publisher</th></tr></thead>\r\n    <tbody>${report.skippedByPattern.map(sw => `<tr><td>${esc(sw.name)}</td><td>${esc(sw.version)}</td><td>${esc(sw.publisher)}</td></tr>`).join('')}</tbody></table>\r\n  </section>`;\r\n\r\n\r\n    const dedupHTML = (report.skippedByDedup || []).length === 0 ? '' : `\r\n  <section id=\"skipped-dedup\">\r\n    <h2>重複去除的軟體（${report.skippedByDedup.length} 筆，未進行掃描）</h2>\r\n    <p class=\"sec-note\">以下軟體在去除版號後與另一條目名稱相同，已由較早出現的條目代表，故略過重複查詢。</p>\r\n    <table><thead><tr><th>Software</th><th>Version</th><th>Publisher</th><th>合併為</th></tr></thead>\r\n    <tbody>${report.skippedByDedup.map(sw => `<tr><td>${esc(sw.name)}</td><td>${esc(sw.version)}</td><td>${esc(sw.publisher)}</td><td style=\"font-size:.78rem;color:#6b7280\">${esc(sw.mergedAs)}</td></tr>`).join('')}</tbody></table>\r\n  </section>`;\r\n\r\n    // Summary table\r\n    const affectedRows = report.results.map(r => {\r\n        const { software, recommendedVersion, cves } = r;\r\n        const unfixedCVE = (cves || []).some(v => !v.fixedVersion);\r\n        let recTd, statusTd;\r\n        if (recommendedVersion) {\r\n            const safe = isSafeVersion(software.version, recommendedVersion);\r\n            recTd = `${recommendedVersion.op === '>=' ? '≥' : '>'} ${esc(recommendedVersion.version)}`;\r\n            statusTd = !safe\r\n                ? `<td class=\"st danger\">✗ 需要升級</td>`\r\n                : unfixedCVE\r\n                    ? `<td class=\"st warn\">? 請手動確認</td>`\r\n                    : `<td class=\"st safe\">✓ 無須升級</td>`;\r\n        } else {\r\n            recTd = '—';\r\n            statusTd = `<td class=\"st warn\">? 請手動確認</td>`;\r\n        }\r\n        return `<tr><td>${esc(software.name)}</td><td>${esc(software.publisher||'—')}</td><td>${esc(software.version||'?')}</td><td>${recTd}</td>${statusTd}</tr>`;\r\n    }).join('\\n');\r\n\r\n    const cleanRows = (report.cleanResults || []).map(r =>\r\n        `<tr><td>${esc(r.software.name)}</td><td>${esc(r.software.publisher||'—')}</td><td>${esc(r.software.version||'?')}</td><td>—</td><td class=\"st safe\">✓ 無弱點</td></tr>`\r\n    ).join('\\n');\r\n\r\n    const tableRows = affectedRows + (cleanRows\r\n        ? `\\n<tr class=\"sep-row\"><td colspan=\"5\" style=\"background:#f0fdf4;color:#16a34a;font-size:.78rem;font-weight:600;padding:5px 12px\">── 以下軟體掃描後無發現 ${esc(report.minSeverity)} 以上弱點 ──</td></tr>\\n` + cleanRows\r\n        : '');\r\n\r\n    // CVE details\r\n    const detailsHTML = report.results.map(r => {\r\n        const { software, cves, recommendedVersion, searchName } = r;\r\n        const installed = software.version || '?';\r\n        const topSev = cves[0]?.severity || 'NONE';\r\n        let recHtml;\r\n        if (recommendedVersion) {\r\n            const safe = isSafeVersion(installed, recommendedVersion);\r\n            recHtml = safe\r\n                ? `<div class=\"rec safe\">✓ 目前版本 (${esc(installed)}) 無弱點，無須升級</div>`\r\n                : `<div class=\"rec danger\">✗ 建議升級至 ${recommendedVersion.op === '>=' ? '≥' : '>'} ${esc(recommendedVersion.version)}（目前：${esc(installed)}）</div>`;\r\n        } else {\r\n            recHtml = `<div class=\"rec warn\">? 無版本修復資訊，請查閱各 CVE 連結</div>`;\r\n        }\r\n        const cveRows = cves.map(cve =>\r\n            `<div class=\"cve\"><div class=\"cve-hd\"><a href=\"${esc(cve.url)}\" target=\"_blank\" class=\"cve-id\">${esc(cve.id)}</a>${badge(cve.severity,cve.cvssScore)}<span class=\"cvss-v\">CVSS${esc(cve.cvssVersion||'')}</span><span class=\"pub\">${(cve.published||'').substring(0,10)}</span></div>\r\n            <p class=\"desc\">${esc(cve.description||'')}</p>${cve.fixedVersion?`<div class=\"fix\">✓ 安全版本：${cve.fixedVersion.op==='>='?'≥':'>'} ${esc(cve.fixedVersion.version)}</div>`:''}</div>`\r\n        ).join('');\r\n        return `\r\n    <details>\r\n      <summary><span class=\"sw-name\">${esc(software.name)}</span><span class=\"sw-ver\">v${esc(installed)}</span>${badge(topSev,'')}<span class=\"cnt\">${cves.length} CVE${cves.length>1?'s':''}</span></summary>\r\n      <div class=\"sw-meta\">Publisher: ${esc(software.publisher||'N/A')} &nbsp;|&nbsp; Search: \"${esc(searchName)}\"</div>\r\n      <div class=\"cve-list\">${cveRows}</div>\r\n      ${recHtml}\r\n    </details>`;\r\n    }).join('\\n');\r\n\r\n    return `<!DOCTYPE html>\r\n<html lang=\"zh-TW\">\r\n<head>\r\n<meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>CVE Report — ${esc(report.generatedAt.substring(0,10))}</title>\r\n<style>\r\n*{box-sizing:border-box;margin:0;padding:0}\r\nbody{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#f3f4f6;color:#1f2937;line-height:1.5}\r\na{color:#2563eb;text-decoration:none}a:hover{text-decoration:underline}\r\nheader{background:#1e3a5f;color:#fff;padding:24px 32px}\r\nheader h1{font-size:1.5rem;font-weight:700;margin-bottom:6px}\r\n.meta{font-size:.83rem;opacity:.8;margin-bottom:16px}\r\n.dash{display:flex;align-items:stretch;gap:0;margin-top:16px;flex-wrap:wrap;gap:2px}\r\n.dash-grp{display:flex;flex-direction:column;gap:5px;padding:0 18px}\r\n.dash-grp:first-child{padding-left:0}\r\n.dash-grp-lbl{font-size:.58rem;text-transform:uppercase;letter-spacing:.12em;opacity:.4;margin-bottom:1px}\r\n.dash-cards{display:flex;align-items:center;gap:4px}\r\n.dash-sep{width:1px;background:rgba(255,255,255,.16);margin:0 4px;align-self:stretch;flex-shrink:0}\r\n.darr{font-size:.65rem;opacity:.3;flex-shrink:0;padding:0 2px}\r\n.dc{border-radius:10px;padding:18px 24px;text-align:center;min-width:100px;flex-shrink:0}\r\n.dc .n{font-size:2.8rem;font-weight:800;line-height:1;letter-spacing:-.03em}\r\n.dc .l{font-size:.69rem;opacity:.72;margin-top:8px;white-space:nowrap}\r\n.dc .s{font-size:.62rem;opacity:.48;margin-top:3px}\r\n.dc.tot{background:rgba(255,255,255,.16)}.dc.tot .n{color:#f1f5f9}\r\n.dc.skip{background:rgba(148,163,184,.14)}.dc.skip .n{color:#94a3b8}\r\n.dc.scan{background:rgba(59,130,246,.22)}.dc.scan .n{color:#93c5fd}\r\n.dc.ok{background:rgba(34,197,94,.18)}.dc.ok .n{color:#86efac}\r\n.dc.hi{background:rgba(239,68,68,.22)}.dc.hi .n{color:#fca5a5}\r\n.dc.neu{background:rgba(234,179,8,.16)}.dc.neu .n{color:#fde68a}\r\nmain{max-width:1100px;margin:24px auto;padding:0 16px}\r\nsection{background:#fff;border-radius:10px;padding:20px 24px;margin-bottom:20px;box-shadow:0 1px 3px rgba(0,0,0,.08)}\r\nh2{font-size:1rem;font-weight:700;margin-bottom:14px;color:#1e3a5f;border-bottom:2px solid #e5e7eb;padding-bottom:8px}\r\n.sec-note{font-size:.85rem;color:#6b7280;margin-bottom:12px}\r\ntable{width:100%;border-collapse:collapse;font-size:.875rem}\r\nth{background:#f9fafb;text-align:left;padding:8px 12px;font-size:.75rem;text-transform:uppercase;letter-spacing:.04em;color:#6b7280;border-bottom:2px solid #e5e7eb}\r\ntd{padding:8px 12px;border-bottom:1px solid #f3f4f6}\r\ntr:last-child td{border-bottom:none}tr:hover td{background:#fafafa}\r\n.st{font-weight:700;font-size:.85rem}.st.safe{color:#16a34a}.st.danger{color:#dc2626}.st.warn{color:#d97706}\r\ndetails{border:1px solid #e5e7eb;border-radius:8px;margin-bottom:8px;overflow:hidden}\r\nsummary{display:flex;align-items:center;gap:8px;padding:11px 16px;cursor:pointer;background:#f9fafb;list-style:none;flex-wrap:wrap;user-select:none}\r\nsummary::-webkit-details-marker{display:none}\r\nsummary::before{content:'▶';font-size:.65rem;color:#9ca3af;transition:transform .15s;flex-shrink:0}\r\ndetails[open]>summary::before{transform:rotate(90deg)}\r\nsummary:hover{background:#f0f0f0}\r\n.sw-name{font-weight:600;font-size:.93rem;flex:1}\r\n.sw-ver{color:#6b7280;font-size:.82rem}\r\n.cnt{color:#6b7280;font-size:.78rem;margin-left:auto}\r\n.sw-meta{padding:5px 16px;font-size:.78rem;color:#9ca3af}\r\n.badge{display:inline-block;padding:2px 7px;border-radius:4px;color:#fff;font-size:.73rem;font-weight:700;white-space:nowrap}\r\n.cve-list{padding:8px 16px 4px}\r\n.cve{background:#f9fafb;border-radius:6px;padding:9px 13px;margin-bottom:7px}\r\n.cve-hd{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-bottom:3px}\r\n.cve-id{font-weight:700;font-family:monospace;font-size:.88rem;color:#1e3a5f}\r\n.cvss-v{font-size:.72rem;color:#9ca3af}\r\n.pub{font-size:.72rem;color:#9ca3af;margin-left:auto}\r\n.desc{font-size:.82rem;color:#4b5563;margin:3px 0}\r\n.fix{font-size:.78rem;color:#16a34a;font-weight:600;margin-top:3px}\r\n.rec{padding:9px 16px;font-size:.85rem;font-weight:600;border-top:1px solid #e5e7eb}\r\n.rec.safe{color:#166534;background:#f0fdf4}.rec.danger{color:#991b1b;background:#fef2f2}.rec.warn{color:#92400e;background:#fffbeb}\r\n\r\n.wl-group{margin-bottom:16px}\r\n.wl-rule{display:inline-block;background:#e0f2fe;color:#0369a1;font-size:.78rem;font-weight:700;padding:2px 10px;border-radius:4px;margin-bottom:6px}\r\nfooter{text-align:center;padding:20px;font-size:.78rem;color:#9ca3af}\r\n</style>\r\n</head>\r\n<body>\r\n<header>\r\n  <h1>CVE Vulnerability Report</h1>\r\n  <div class=\"meta\">\r\n    Generated: ${esc(formatDateTime(report.generatedAt))} &nbsp;|&nbsp;\r\n    Host: ${esc(report.hostname||'?')} &nbsp;|&nbsp;\r\n    IP: ${esc(report.ip||'?')} &nbsp;|&nbsp;\r\n    User: ${esc(report.username||'?')} &nbsp;|&nbsp;\r\n    Min Severity: <strong>${esc(report.minSeverity)}</strong> &nbsp;|&nbsp;\r\n    CVE 日期範圍：<strong>${esc(minYearLabel)}</strong>\r\n  </div>\r\n  <div class=\"dash\">\r\n    <div class=\"dash-grp\">\r\n      <div class=\"dash-grp-lbl\">軟體清單</div>\r\n      <div class=\"dash-cards\">\r\n        <div class=\"dc tot\"><div class=\"n\">${report.summary.totalSoftware}</div><div class=\"l\">軟體總計</div></div>\r\n        <span class=\"darr\">▶</span>\r\n        <div class=\"dc skip\"><div class=\"n\">${(report.whitelisted||[]).length}</div><div class=\"l\">白名單略過</div></div>\r\n        <span class=\"darr\">▶</span>\r\n        <div class=\"dc skip\"><div class=\"n\">${(report.skippedByPattern||[]).length+(report.skippedByDedup||[]).length}</div><div class=\"l\">子元件/重複略過</div><div class=\"s\">${(report.skippedByPattern||[]).length} 子元件・${(report.skippedByDedup||[]).length} 重複</div></div>\r\n        <span class=\"darr\">▶</span>\r\n        <div class=\"dc scan\"><div class=\"n\">${report.summary.queriedSoftware}</div><div class=\"l\">實際掃描</div></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"dash-sep\"></div>\r\n    <div class=\"dash-grp\">\r\n      <div class=\"dash-grp-lbl\">掃描結果</div>\r\n      <div class=\"dash-cards\">\r\n        <div class=\"dc scan\"><div class=\"n\">${report.summary.queriedSoftware}</div><div class=\"l\">實際掃描</div></div>\r\n        <span class=\"darr\">▶</span>\r\n        <div class=\"dc ok\"><div class=\"n\">${cleanCount}</div><div class=\"l\">無弱點</div></div>\r\n        <span class=\"darr\">▶</span>\r\n        <div class=\"dc ${report.summary.affectedSoftware>0?'hi':'ok'}\"><div class=\"n\">${report.summary.affectedSoftware}</div><div class=\"l\">發現弱點</div><div class=\"s\">${report.summary.totalCVEs} 筆 CVE</div></div>\r\n        ${report.summary.affectedSoftware>0?`<span class=\"darr\">▶</span><div class=\"dc ok\"><div class=\"n\">${alreadySafe}</div><div class=\"l\">已是最新版</div></div><span class=\"darr\">▶</span><div class=\"dc ${needUpgrade>0?'hi':'ok'}\"><div class=\"n\">${needUpgrade}</div><div class=\"l\">建議升級</div></div>${noRecCount>0?`<span class=\"darr\">▶</span><div class=\"dc neu\"><div class=\"n\">${noRecCount}</div><div class=\"l\">請手動確認</div></div>`:''}` : ''}\r\n      </div>\r\n    </div>\r\n  </div>\r\n</header>\r\n<main>\r\n  <section>\r\n    <h2>升級建議摘要（共 ${report.summary.queriedSoftware} 筆：${needUpgrade} 需升級・${alreadySafe} 已最新版・${cleanCount} 無弱點${noRecCount>0?'・'+noRecCount+' 請手動確認':''}）</h2>\r\n    <table>\r\n      <thead><tr><th>Software</th><th>Publisher</th><th>已安裝版本</th><th>最低安全版本（需達到）</th><th>狀態</th></tr></thead>\r\n      <tbody>${tableRows||'<tr><td colspan=\"5\" style=\"color:#6b7280;text-align:center\">所有掃描軟體均無發現弱點</td></tr>'}</tbody>\r\n    </table>\r\n  </section>\r\n  <section>\r\n    <h2>CVE 詳細資訊（點擊展開）</h2>\r\n    ${detailsHTML||'<p class=\"sec-note\">所有掃描軟體均無發現 CVE</p>'}\r\n  </section>\r\n  ${wlHTML}${patternHTML}${dedupHTML}\r\n</main>\r\n<footer>NIST NVD CVE Scanner (Web) &nbsp;·&nbsp; ${esc(report.generatedAt)}<br>This product uses data from the NVD API but is not endorsed or certified by the NVD.</footer>\r\n</body>\r\n</html>`;\r\n}\r\n\r\n// ─── UI elements ──────────────────────────────────────────────────────────────\r\nconst dropZone    = document.getElementById('drop-zone');\r\nconst fileInput   = document.getElementById('file-input');\r\nconst fileInfo    = document.getElementById('file-info');\r\nconst scanBtn     = document.getElementById('scan-btn');\r\nconst cancelBtn   = document.getElementById('cancel-btn');\r\nconst scanStatus  = document.getElementById('scan-status');\r\nconst portableList = document.getElementById('portable-list');\r\nconst manualList   = document.getElementById('manual-list');\r\n\r\n// ─── Portable rows ────────────────────────────────────────────────────────────\r\nfunction addPortableRow(name = '', version = '') {\r\n    const row = document.createElement('div');\r\n    row.className = 'portable-row';\r\n    row.innerHTML = '<input type=\"text\" class=\"pt-name\" placeholder=\"軟體名稱（例：Eclipse IDE）\">'\r\n                  + '<input type=\"text\" class=\"pt-ver\"  placeholder=\"版本號（例：202506）\">'\r\n                  + '<button type=\"button\" class=\"pt-del\" title=\"移除\">✕</button>';\r\n    row.querySelector('.pt-name').value = name;\r\n    row.querySelector('.pt-ver').value  = version;\r\n    row.querySelector('.pt-del').onclick = () => row.remove();\r\n    portableList.appendChild(row);\r\n}\r\ndocument.getElementById('add-portable-btn').addEventListener('click', () => addPortableRow());\r\n// Portables are pre-populated by the server-injected script (runs after this block).\r\n// portable-section visibility is also controlled by the server-injected script.\r\n\r\n// ─── Scan button state ────────────────────────────────────────────────────────\r\nfunction updateScanBtnState() {\r\n    if (activeTab === 'file') {\r\n        scanBtn.disabled = !scanData;\r\n        scanStatus.textContent = scanData ? `已就緒 — ${scanData.softwares.length} 筆軟體` : '請先上傳 scan.json';\r\n    } else {\r\n        const hasAny = [...manualList.querySelectorAll('.mn-name')].some(i => i.value.trim());\r\n        scanBtn.disabled = !hasAny;\r\n        scanStatus.textContent = hasAny ? '已就緒（手動輸入模式）' : '請新增至少一筆軟體';\r\n    }\r\n}\r\n\r\n// ─── Manual entry rows ────────────────────────────────────────────────────────\r\nfunction addManualRow(name = '', version = '') {\r\n    const row = document.createElement('div');\r\n    row.className = 'manual-row';\r\n    row.innerHTML = '<input type=\"text\" class=\"mn-name\" placeholder=\"軟體名稱（例：Eclipse IDE）\">'\r\n                  + '<input type=\"text\" class=\"mn-ver\"  placeholder=\"版本號（例：2025.06）\">'\r\n                  + '<button type=\"button\" class=\"mn-del\" title=\"移除\">✕</button>';\r\n    row.querySelector('.mn-name').value = name;\r\n    row.querySelector('.mn-ver').value  = version;\r\n    row.querySelector('.mn-del').onclick = () => { row.remove(); updateScanBtnState(); };\r\n    row.querySelector('.mn-name').addEventListener('input', updateScanBtnState);\r\n    manualList.appendChild(row);\r\n    updateScanBtnState();\r\n}\r\ndocument.getElementById('add-manual-btn').addEventListener('click', () => addManualRow());\r\naddManualRow(); // default empty row\r\n\r\n// ─── Tab switching ────────────────────────────────────────────────────────────\r\ndocument.querySelectorAll('.tab-btn').forEach(btn => {\r\n    btn.addEventListener('click', () => {\r\n        const target = btn.dataset.tab;\r\n        const fromBottom = btn.closest('.tab-bar-bottom') != null;\r\n        if (target === activeTab) {\r\n            if (fromBottom) document.querySelector('.tab-bar').scrollIntoView({ behavior: 'smooth', block: 'start' });\r\n            return;\r\n        }\r\n        activeTab = target;\r\n        document.querySelectorAll('.tab-btn').forEach(b => b.classList.toggle('active', b.dataset.tab === target));\r\n        document.querySelectorAll('.tab-panel').forEach(p => p.classList.toggle('active', p.id === `tab-${target}`));\r\n        updateScanBtnState();\r\n        if (fromBottom) document.querySelector('.tab-bar').scrollIntoView({ behavior: 'smooth', block: 'start' });\r\n    });\r\n});\r\n\r\n// Restore settings\r\nconst LS = { key: 'nvd_api_key', wl: 'nvd_whitelist', sev: 'nvd_severity', year: 'nvd_min_year', max: 'nvd_max_cves' };\r\nconst $id = id => document.getElementById(id);\r\nconst restore = (id, lsKey) => { const v = localStorage.getItem(lsKey); if (v) $id(id).value = v; };\r\nrestore('api-key', LS.key);\r\nrestore('whitelist', LS.wl);\r\n// If the stored value is the old default (MEDIUM), clear it so the new HTML default (HIGH) takes effect.\r\nif (localStorage.getItem(LS.sev) === 'MEDIUM') localStorage.removeItem(LS.sev);\r\nrestore('min-severity', LS.sev);\r\nrestore('min-year', LS.year);\r\nrestore('max-cves', LS.max);\r\n\r\n// ─── File handling ────────────────────────────────────────────────────────────\r\nfunction loadScanFile(file) {\r\n    if (!file) return;\r\n    const reader = new FileReader();\r\n    reader.onload = e => {\r\n        try {\r\n            const data = JSON.parse(e.target.result);\r\n            if (!Array.isArray(data.softwares)) throw new Error('缺少 softwares 陣列（請確認為 cve-checker.js 或 findSW.ps1 產生的格式）');\r\n            scanData = data;\r\n            dropZone.classList.add('has-file');\r\n            dropZone.querySelector('.dz-icon').textContent = '✅';\r\n            dropZone.querySelector('.dz-label').textContent = file.name;\r\n            dropZone.querySelector('.dz-sub').textContent =\r\n                `${data.softwares.length} 筆軟體 · Host: ${data.hostname||'?'} · User: ${data.username||'?'}`;\r\n            fileInfo.style.display = 'block';\r\n            fileInfo.innerHTML = `<strong>${esc(file.name)}</strong> — ${data.softwares.length} 筆 &nbsp;·&nbsp; Host: <strong>${esc(data.hostname||'?')}</strong> &nbsp;·&nbsp; User: <strong>${esc(data.username||'?')}</strong> &nbsp;·&nbsp; Generated: ${esc((data.generatedAt||'').substring(0,10))}`;\r\n            updateScanBtnState();\r\n        } catch (err) {\r\n            alert(`JSON 格式錯誤：${err.message}`);\r\n        }\r\n    };\r\n    reader.readAsText(file, 'utf-8');\r\n}\r\n\r\nfileInput.addEventListener('change', e => loadScanFile(e.target.files[0]));\r\ndropZone.addEventListener('click', () => { if (!scanData) fileInput.click(); });\r\ndropZone.addEventListener('dragover', e => { e.preventDefault(); dropZone.classList.add('drag-over'); });\r\ndropZone.addEventListener('dragleave', e => { if (!dropZone.contains(e.relatedTarget)) dropZone.classList.remove('drag-over'); });\r\ndropZone.addEventListener('drop', e => {\r\n    e.preventDefault();\r\n    dropZone.classList.remove('drag-over');\r\n    loadScanFile(e.dataTransfer.files[0]);\r\n});\r\n\r\n// ─── Progress logging ─────────────────────────────────────────────────────────\r\nfunction logLineTo(tab, html, cls) {\r\n    const log = $id(`${tab}-progress-log`);\r\n    if (!log) return;\r\n    const d = document.createElement('div');\r\n    if (cls) d.className = cls;\r\n    d.innerHTML = html;\r\n    log.appendChild(d);\r\n    log.scrollTop = log.scrollHeight;\r\n}\r\nfunction logLine(html, cls) { logLineTo(activeTab, html, cls); }\r\nfunction logClear() { $id(`${activeTab}-progress-log`).innerHTML = ''; }\r\nfunction updateBar(done, total, cves) {\r\n    $id(`${activeTab}-progress-bar`).style.width = `${total > 0 ? Math.round(done/total*100) : 0}%`;\r\n    const left = Math.max(0, total - done);\r\n    $id(`${activeTab}-progress-stats`).innerHTML =\r\n        `<span>已掃描 <strong>${done}</strong>/${total}</span>` +\r\n        `<span>發現 <strong>${cves}</strong> 筆 CVE</span>` +\r\n        (left > 0 ? `<span>剩餘 <strong>${left}</strong> 項</span>` : '');\r\n}\r\n\r\n// ─── Main scan ────────────────────────────────────────────────────────────────\r\nscanBtn.addEventListener('click', async () => {\r\n    const isManual = activeTab === 'manual';\r\n    const scanTab  = activeTab;\r\n    if (!isManual && !scanData) return;\r\n\r\n    // Read settings\r\n    const apiKey     = $id('api-key').value.trim();\r\n    const wlRaw      = $id('whitelist').value;\r\n    const minSev     = $id('min-severity').value;\r\n    const minYearVal = $id('min-year').value.trim();\r\n    const minYear    = minYearVal ? (parseInt(minYearVal) || 0) : (new Date().getFullYear() - 5);\r\n    const maxCves    = Math.max(1, parseInt($id('max-cves').value) || 50);\r\n    const whitelist  = wlRaw.split(',').map(s => s.trim()).filter(Boolean);\r\n    const delay      = window.__NVD_DELAY__ ?? (apiKey ? 700 : 6500);\r\n    const minIdx     = SEVERITY_ORDER.indexOf(minSev);\r\n\r\n    // Persist settings\r\n    localStorage.setItem(LS.key,  apiKey);\r\n    localStorage.setItem(LS.wl,   wlRaw);\r\n    localStorage.setItem(LS.sev,  minSev);\r\n    localStorage.setItem(LS.year, minYearVal);\r\n    localStorage.setItem(LS.max,  String(maxCves));\r\n\r\n    abortController = new AbortController();\r\n    const signal = abortController.signal;\r\n\r\n    // UI: scanning state\r\n    scanBtn.disabled = true;\r\n    cancelBtn.style.display = 'inline-block';\r\n    cancelBtn.disabled = false;\r\n    scanStatus.textContent = '掃描中…';\r\n    document.querySelectorAll('.tab-btn').forEach(b => b.disabled = true);\r\n    $id(`${activeTab}-result-card`).style.display = 'none';\r\n    $id(`${activeTab}-progress-card`).style.display = 'block';\r\n    logClear();\r\n\r\n    // Revoke old download URLs for this tab only\r\n    for (const u of tabBlobUrls[activeTab]) URL.revokeObjectURL(u);\r\n    tabBlobUrls[activeTab] = [];\r\n\r\n    // ── Build query map ────────────────────────────────────────────────────────\r\n    const queryMap       = new Map();  // searchName → sw\r\n    let whitelisted    = [];\r\n    let skippedByPat   = [];\r\n    let skippedByDedup = [];\r\n    let portableEntries = [];\r\n\r\n    if (isManual) {\r\n        for (const row of manualList.querySelectorAll('.manual-row')) {\r\n            const name = row.querySelector('.mn-name').value.trim();\r\n            const ver  = row.querySelector('.mn-ver').value.trim();\r\n            if (name && !queryMap.has(name)) queryMap.set(name, { name, version: ver, publisher: '' });\r\n        }\r\n    } else {\r\n        for (const sw of scanData.softwares) {\r\n            const rule = matchWhitelist(sw, whitelist);\r\n            if (rule) { whitelisted.push({ name: sw.name, version: sw.version||'', publisher: sw.publisher||'', matchedRule: rule }); continue; }\r\n            if (shouldSkip(sw.name)) { skippedByPat.push({ name: sw.name, version: sw.version||'', publisher: sw.publisher||'' }); continue; }\r\n            const sn = cleanProductName(sw.name);\r\n            if (!queryMap.has(sn)) queryMap.set(sn, sw);\r\n            else skippedByDedup.push({ name: sw.name, version: sw.version||'', publisher: sw.publisher||'', mergedAs: sn });\r\n        }\r\n        // ── Add portable entries (bypass whitelist + skip-patterns) ──────────\r\n        for (const row of portableList.querySelectorAll('.portable-row')) {\r\n            const name = row.querySelector('.pt-name').value.trim();\r\n            const ver  = row.querySelector('.pt-ver').value.trim();\r\n            if (!name) continue;\r\n            portableEntries.push({ name, version: ver, publisher: '' });\r\n        }\r\n        for (const pt of portableEntries) {\r\n            if (!queryMap.has(pt.name)) queryMap.set(pt.name, pt);\r\n        }\r\n    }\r\n\r\n    const total        = queryMap.size;\r\n    const portableNote = portableEntries.length ? ` + <span class=\"l-b\">${portableEntries.length}</span> Portable` : '';\r\n    const modeTag      = isManual ? ' <span class=\"l-info\">[手動輸入]</span>' : '';\r\n    logLine(`<span class=\"l-info\">▶ 開始掃描</span> <span class=\"l-b\">${total}</span> 項軟體${portableNote}${modeTag}`\r\n        + (isManual ? '' : ` <span class=\"l-gray\">(白名單:${whitelisted.length} 子元件:${skippedByPat.length} 去重:${skippedByDedup.length})</span>`));\r\n    const apiKeyLabel = window.__NVD_PROXY__\r\n        ? (delay <= 700 ? '伺服器代理(已設定)' : '伺服器代理(未設定,6.5秒/次)')\r\n        : (apiKey ? '已設定' : '未設定(6.5秒/次)');\r\n    logLine(`<span class=\"l-gray\">設定：嚴重度≥${minSev}，年份≥${minYear}，每項最多${maxCves}筆，`\r\n        + `API Key:${apiKeyLabel}，預估${Math.ceil(total*delay/1000)}秒</span>`);\r\n    logLine('─'.repeat(64), 'l-gray');\r\n\r\n    const results      = [];\r\n    const cleanResults = [];\r\n    let idx = 0, totalCVEs = 0;\r\n    let scanSid = null;\r\n    const cpeBasesMap = new Map(); // searchName → cpeBases[] (only for portable items)\r\n\r\n    try {\r\n        // ── Shared CVE processing helper ──────────────────────────────────────\r\n        const processOneResult = (searchName, sw, resp) => {\r\n            const cpeBases = cpeBasesMap.get(searchName) || null;\r\n            const cpeBase  = cpeBases ? cpeBases[0] : null;\r\n\r\n            const allCVEs = (resp.vulnerabilities || []).map(v => ({ ...v, _cvss: getCvss(v.cve) }));\r\n\r\n            const checked = allCVEs\r\n                .filter(v => SEVERITY_ORDER.indexOf(v._cvss.severity) >= minIdx)\r\n                .filter(v => !minYear || new Date(v.cve.published).getFullYear() >= minYear)\r\n                .map(v => {\r\n                    const rel = cpeBases\r\n                        ? cveMatchesCPEBase(v.cve, cpeBases)\r\n                        : cveRelevanceCheck(v.cve, searchName);\r\n                    let finalRel = rel;\r\n                    let mis = null;\r\n                    if (rel === false) {\r\n                        mis = cpeBases\r\n                            ? `CPE 條目中無 ${cpeBases.map(b => `:${b.vendor}:${b.product}:`).join(' / ')}，非本軟體直接受影響的 CVE`\r\n                            : `CPE 條目中未含「${searchName}」相關字詞`;\r\n                    } else if (rel === true && sw.version && sw.version !== '?') {\r\n                        const exactCheck = cveExactVersionCheck(sw.version, v.cve, searchName, cpeBase);\r\n                        if (exactCheck && !exactCheck.affected) {\r\n                            finalRel = false;\r\n                            mis = `只有特定版本 ${exactCheck.versions.join('、')} 受影響，已安裝版本 ${sw.version} 不符`;\r\n                        }\r\n                    }\r\n                    return { ...v, _rel: finalRel, _mis: mis };\r\n                });\r\n\r\n            const mismatched = checked.filter(v => v._rel !== true).map(v => ({\r\n                id: v.cve.id, url: `https://nvd.nist.gov/vuln/detail/${v.cve.id}`,\r\n                severity: v._cvss.severity, cvssScore: v._cvss.score, cvssVersion: v._cvss.version,\r\n                description: v.cve.descriptions?.find(d => d.lang==='en')?.value || '',\r\n                published: v.cve.published, mismatchReason: v._mis,\r\n            }));\r\n\r\n            const relevant = checked\r\n                .filter(v => v._rel === true) // only confirmed-relevant CVEs (null = no CPE data → filtered out)\r\n                .sort((a, b) => (b.cve.published||'').localeCompare(a.cve.published||''));\r\n\r\n            mismatched.sort((a, b) => (b.published||'').localeCompare(a.published||''));\r\n\r\n            if (relevant.length === 0) {\r\n                logLine(`<span class=\"l-ok\">  ✓ 無弱點（${esc(minSev)}以上）</span>`);\r\n                cleanResults.push({\r\n                    software: { name: sw.name, version: sw.version||'', publisher: sw.publisher||'' },\r\n                    searchName, cpeBase: cpeBase || null, mismatchedCVEs: mismatched,\r\n                });\r\n                return { summary: `✓ 無弱點（取回${allCVEs.length}筆均不符條件）`, cveDetails: [] };\r\n            } else {\r\n                totalCVEs += relevant.length;\r\n                const cveObjs = relevant.map(v => ({\r\n                    id: v.cve.id,\r\n                    url: `https://nvd.nist.gov/vuln/detail/${v.cve.id}`,\r\n                    severity: v._cvss.severity,\r\n                    cvssScore: v._cvss.score,\r\n                    cvssVersion: v._cvss.version,\r\n                    description: v.cve.descriptions?.find(d => d.lang==='en')?.value || '',\r\n                    published: v.cve.published,\r\n                    lastModified: v.cve.lastModified,\r\n                    fixedVersion: extractFixedVersion(v.cve, searchName, cpeBase),\r\n                }));\r\n                const rec = getRecommendedVersion(relevant, searchName, cpeBase);\r\n                const sortedCves = [...cveObjs].sort((a, b) => (b.published||'').localeCompare(a.published||''));\r\n                for (const cve of sortedCves) {\r\n                    const cls = (cve.severity==='CRITICAL'||cve.severity==='HIGH') ? 'l-err' : 'l-warn';\r\n                    const fix = cve.fixedVersion\r\n                        ? `<span class=\"l-ok\"> ✓ 安全版本：${cve.fixedVersion.op==='>='?'≥':'>'} ${esc(cve.fixedVersion.version)}</span>`\r\n                        : `<span class=\"l-warn\"> ⚠ 無修復版本資訊</span>`;\r\n                    logLine(`  <span class=\"${cls}\"><a href=\"${cve.url}\" target=\"_blank\" rel=\"noopener\">${esc(cve.id)}</a> [${cve.severity} ${cve.cvssScore}]</span> <span class=\"l-gray\">${(cve.published||'').substring(0,10)}</span>${fix}`);\r\n                }\r\n                const hasUnfixed = cveObjs.some(c => !c.fixedVersion);\r\n                const needManualCheck = hasUnfixed;\r\n                if (rec) {\r\n                    if (!isSafeVersion(sw.version, rec)) {\r\n                        logLine(`  <span class=\"l-err\">→ 建議升級至 ${rec.op==='>='?'≥':'>'} ${esc(rec.version)}（目前：${esc(sw.version||'?')}）</span>`);\r\n                    } else if (needManualCheck) {\r\n                        logLine(`  <span class=\"l-warn\">→ 現有版本已達部分修復要求，但仍有 CVE 無修復版本資訊，請手動確認</span>`);\r\n                    } else {\r\n                        logLine(`  <span class=\"l-ok\">→ 目前版本 (${esc(sw.version)}) 已是安全版，無須升級</span>`);\r\n                    }\r\n                } else {\r\n                    logLine(`  <span class=\"l-warn\">→ 無修復版本資訊，請手動確認</span>`);\r\n                }\r\n                results.push({\r\n                    software: { name: sw.name, version: sw.version||'', publisher: sw.publisher||'', installDate: sw.installDate||null },\r\n                    searchName, cpeBase: cpeBase || null, recommendedVersion: rec, cveCount: cveObjs.length,\r\n                    cves: cveObjs, mismatchedCVEs: mismatched,\r\n                });\r\n                const maxSev = cveObjs.reduce((m, v) =>\r\n                    SEVERITY_ORDER.indexOf(v.severity) > SEVERITY_ORDER.indexOf(m) ? v.severity : m, 'NONE');\r\n                const cveDetails = sortedCves.map(cve => {\r\n                    const fixStr = cve.fixedVersion\r\n                        ? `✓ 安全版本：${cve.fixedVersion.op === '>=' ? '≥' : '>'} ${cve.fixedVersion.version}`\r\n                        : '⚠ 無修復版本資訊';\r\n                    return `  ${cve.id} [${cve.severity} ${cve.cvssScore}] ${(cve.published||'').substring(0,10)} ${fixStr}`;\r\n                });\r\n                const n = `${cveObjs.length}/${allCVEs.length}筆[${maxSev}]`;\r\n                if (!rec)                                                return { summary: `→ ${n}，請手動確認`,                                                                 cveDetails };\r\n                if (isSafeVersion(sw.version, rec) && !needManualCheck) return { summary: `✓ ${n}，目前版本已達修復版本`,                                                        cveDetails };\r\n                if (isSafeVersion(sw.version, rec))                     return { summary: `→ ${n}，現有版本已達部分修復要求，但仍有 CVE 無修復版本資訊，請手動確認`,              cveDetails };\r\n                return                                                          { summary: `→ ${n}，建議升級至 ${rec.op==='>='?'≥':'>'} ${rec.version}`, cveDetails };\r\n            }\r\n        };\r\n\r\n        // ── CPE pre-lookup for portable items ─────────────────────────────────\r\n        if (!isManual && portableEntries.length > 0) {\r\n            logLine(`<span class=\"l-gray\">── CPE 識別碼查找（${portableEntries.length} 個 Portable 軟體）…</span>`);\r\n            let firstCpe = true;\r\n            for (const pt of portableEntries) {\r\n                if (signal.aborted) break;\r\n                if (!firstCpe && !window.__NVD_PROXY__) await sleep(delay, signal);\r\n                firstCpe = false;\r\n                const nameWords = pt.name.toLowerCase().replace(/[^a-z0-9]/g, ' ').split(/\\s+/).filter(w => w.length >= 2);\r\n                try {\r\n                    let cpeData;\r\n                    if (window.__NVD_PROXY__) {\r\n                        const r = await fetch(`/api/cpe?keyword=${encodeURIComponent(pt.name)}`, { signal });\r\n                        if (!r.ok) throw new Error(`HTTP ${r.status}`);\r\n                        cpeData = await r.json();\r\n                    } else {\r\n                        const NVD_CPE_BASE = 'https://services.nvd.nist.gov/rest/json/cpes/2.0';\r\n                        const url = `${NVD_CPE_BASE}?keywordSearch=${encodeURIComponent(pt.name)}&resultsPerPage=10000`;\r\n                        cpeData = await nvdFetch(url, apiKey, signal);\r\n                    }\r\n                    const bases = findAllCPEBases(cpeData.products || [], nameWords);\r\n                    if (bases.length > 0) {\r\n                        cpeBasesMap.set(pt.name, bases);\r\n                        logLine(`<span class=\"l-gray\">  ${esc(pt.name)} → CPE: ${bases.map(b => `${b.vendor}:${b.product}`).join(' | ')}</span>`);\r\n                    } else {\r\n                        logLine(`<span class=\"l-warn\">  ${esc(pt.name)} → 未找到對應 CPE，改用關鍵字比對</span>`);\r\n                    }\r\n                } catch (e) {\r\n                    if (e.name === 'AbortError') throw e;\r\n                    logLine(`<span class=\"l-warn\">  ${esc(pt.name)} → CPE 查找失敗：${esc(e.message)}，改用關鍵字比對</span>`);\r\n                }\r\n            }\r\n            if (!firstCpe && !window.__NVD_PROXY__) await sleep(delay, signal); // delay before first CVE query\r\n            logLine('─'.repeat(64), 'l-gray');\r\n        }\r\n\r\n        if (window.__NVD_PROXY__) {\r\n            // ── Proxy mode: stream from server, process each item as it arrives ─\r\n            const scanResp = await fetch('/api/scan', {\r\n                method: 'POST',\r\n                headers: { 'Content-Type': 'application/json' },\r\n                body: JSON.stringify({\r\n                    keywords: [...queryMap.keys()],\r\n                    maxCves,\r\n                    meta: {\r\n                        minSeverity:      minSev,\r\n                        minYear,\r\n                        portableCount:    portableEntries.length,\r\n                        whitelistedCount: whitelisted.length,\r\n                        skippedCount:     skippedByPat.length,\r\n                        dedupCount:       skippedByDedup.length,\r\n                    },\r\n                }),\r\n                signal,\r\n            });\r\n            if (!scanResp.ok) throw new Error(`伺服器掃描失敗：HTTP ${scanResp.status}`);\r\n\r\n            const reader = scanResp.body.getReader();\r\n            const dec = new TextDecoder();\r\n            let buf = '';\r\n            outer: while (true) {\r\n                const { done, value } = await reader.read();\r\n                if (done) break;\r\n                buf += dec.decode(value, { stream: true });\r\n                let nl;\r\n                while ((nl = buf.indexOf('\\n')) !== -1) {\r\n                    const line = buf.slice(0, nl).trim();\r\n                    buf = buf.slice(nl + 1);\r\n                    if (!line) continue;\r\n                    const item = JSON.parse(line);\r\n                    if (item.done) break outer;\r\n                    if (item.sid) { scanSid = item.sid; continue; }\r\n                    const searchName = item.keyword;\r\n                    const sw = queryMap.get(searchName);\r\n                    if (!sw) continue;\r\n                    idx++;\r\n                    logLine(`<span class=\"l-gray\">[${idx}/${total}]</span> <span class=\"l-b\">${esc(sw.name)}</span> <span class=\"l-gray\">v${esc(sw.version||'?')}</span>`);\r\n                    logLine(`<span class=\"l-gray\">  search: \"${esc(searchName)}\"</span>`);\r\n                    let itemSummary = null, itemCveDetails = [];\r\n                    try {\r\n                        if (item.error) throw new Error(item.error);\r\n                        ({ summary: itemSummary, cveDetails: itemCveDetails } = processOneResult(searchName, sw, item.data));\r\n                    } catch (apiErr) {\r\n                        if (apiErr.name === 'AbortError') throw apiErr;\r\n                        itemSummary = `✗ 失敗：${apiErr.message}`;\r\n                        logLine(`  <span class=\"l-err\">✗ 掃描失敗：${esc(apiErr.message)}</span>`);\r\n                    }\r\n                    if (scanSid && itemSummary) {\r\n                        const logLines = [\r\n                            `[${idx}/${total}] ${sw.name} v${sw.version||'?'} ${itemSummary}`,\r\n                            ...itemCveDetails,\r\n                        ];\r\n                        fetch('/api/log', {\r\n                            method: 'POST',\r\n                            headers: { 'Content-Type': 'application/json' },\r\n                            body: JSON.stringify({ sid: scanSid, msg: logLines.join('\\n') }),\r\n                        }).catch(() => {});\r\n                    }\r\n                    updateBar(idx, total, totalCVEs);\r\n                }\r\n            }\r\n        } else {\r\n            // ── Direct mode: call NVD API per item ────────────────────────────\r\n            for (const [searchName, sw] of queryMap) {\r\n                if (signal.aborted) break;\r\n                idx++;\r\n                updateBar(idx - 1, total, totalCVEs);\r\n                logLine(`<span class=\"l-gray\">[${idx}/${total}]</span> <span class=\"l-b\">${esc(sw.name)}</span> <span class=\"l-gray\">v${esc(sw.version||'?')}</span>`);\r\n                logLine(`<span class=\"l-gray\">  search: \"${esc(searchName)}\"</span>`);\r\n\r\n                if (idx > 1) await sleep(delay, signal);\r\n                if (signal.aborted) break;\r\n\r\n                try {\r\n                    const resp = await searchCVEs(searchName, apiKey, maxCves, minYear, signal,\r\n                        msg => logLine(`  <span class=\"l-warn\">  🔄 ${msg}</span>`));\r\n                    processOneResult(searchName, sw, resp);\r\n                } catch (apiErr) {\r\n                    if (apiErr.name === 'AbortError') throw apiErr;\r\n                    logLine(`  <span class=\"l-err\">✗ 重試 ${MAX_FETCH_RETRIES} 次後仍失敗：${esc(apiErr.message)}</span>`);\r\n                    if (/CORS/i.test(apiErr.message)) {\r\n                        logLine(`  <span class=\"l-warn\">  提示：可能是 CORS 問題。請確認可直接連線 NIST NVD (services.nvd.nist.gov)，或改用本機 Node.js 版本。</span>`);\r\n                    }\r\n                }\r\n            }\r\n        }\r\n    } catch (e) {\r\n        if (e.name !== 'AbortError') logLine(`<span class=\"l-err\">✗ 未預期錯誤：${esc(e.message)}</span>`);\r\n    }\r\n\r\n    const cancelled = signal.aborted;\r\n    // Calculate status breakdown (also used by pills below)\r\n    const needUp      = results.filter(r => r.recommendedVersion && !isSafeVersion(r.software.version, r.recommendedVersion)).length;\r\n    const safeAlready = results.filter(r => r.recommendedVersion && isSafeVersion(r.software.version, r.recommendedVersion) && !r.cves.some(v => !v.fixedVersion)).length;\r\n    const manCheck    = results.filter(r => !r.recommendedVersion || (isSafeVersion(r.software.version, r.recommendedVersion) && r.cves.some(v => !v.fixedVersion))).length;\r\n    logLine('─'.repeat(64), 'l-gray');\r\n    if (cancelled) {\r\n        logLine('<span class=\"l-warn\">■ 掃描已取消</span>');\r\n    } else {\r\n        const parts = [];\r\n        if (safeAlready > 0) parts.push(`${safeAlready} 個已為最新版`);\r\n        if (needUp > 0) parts.push(`${needUp} 個建議升級`);\r\n        if (manCheck > 0) parts.push(`${manCheck} 個待確認`);\r\n        const breakdown = results.length > 0 && parts.length > 0 ? `，其中 ${parts.join('，')}` : '';\r\n        logLine(`<span class=\"l-ok l-b\">✓ 掃描完成</span> — ${idx} 項掃描・${cleanResults.length} 項無弱點，${results.length} 項有弱點${breakdown}`);\r\n    }\r\n    if (scanSid) {\r\n        const summaryMsg = cancelled\r\n            ? `■ 掃描取消（已完成 ${idx}/${total}）`\r\n            : `✓ 掃描完成 — ${idx}項掃描・${cleanResults.length}項無弱點，${results.length}項有弱點${needUp ? `（建議升級:${needUp}）` : ''}`;\r\n        fetch('/api/log', {\r\n            method: 'POST',\r\n            headers: { 'Content-Type': 'application/json' },\r\n            body: JSON.stringify({ sid: scanSid, msg: summaryMsg }),\r\n        }).catch(() => {});\r\n    }\r\n    updateBar(idx, total, totalCVEs);\r\n\r\n    // ── Build report object (mirrors cve-checker.js structure) ────────────────\r\n    const report = {\r\n        generatedAt: new Date().toISOString(),\r\n        source: isManual ? 'Web (手動輸入)' : 'Web (scan.json)',\r\n        hostname: isManual ? '' : scanData.hostname || '',\r\n        ip: isManual ? '' : scanData.ip || '',\r\n        username: isManual ? '' : (scanData.username || '').toLowerCase(),\r\n        scanDate: isManual ? null : scanData.generatedAt,\r\n        minSeverity: minSev,\r\n        minYear,\r\n        summary: {\r\n            totalSoftware: isManual ? queryMap.size : (scanData.softwares.length + portableEntries.length),\r\n            queriedSoftware: idx,\r\n            affectedSoftware: results.length,\r\n            totalCVEs,\r\n        },\r\n        results,\r\n        cleanResults,\r\n        whitelisted,\r\n        skippedByPattern: skippedByPat,\r\n        skippedByDedup,\r\n        errors: [],\r\n    };\r\n\r\n    // ── Build report blobs ─────────────────────────────────────────────────────\r\n    const htmlStr  = buildHTMLReport(report);\r\n    const jsonStr  = JSON.stringify(report, null, 2);\r\n    const htmlBlob = new Blob([htmlStr], { type: 'text/html;charset=utf-8' });\r\n    const jsonBlob = new Blob([jsonStr], { type: 'application/json;charset=utf-8' });\r\n    const htmlUrl  = URL.createObjectURL(htmlBlob);\r\n    const jsonUrl  = URL.createObjectURL(jsonBlob);\r\n    tabBlobUrls[scanTab].push(htmlUrl, jsonUrl);\r\n    const slog = msg => {\r\n        if (!scanSid) return;\r\n        fetch('/api/log', { method: 'POST', headers: { 'Content-Type': 'application/json' },\r\n            body: JSON.stringify({ sid: scanSid, msg }) }).catch(() => {});\r\n    };\r\n    $id(`${scanTab}-open-report-btn`).onclick = () => {\r\n        window.open(htmlUrl, '_blank');\r\n        slog('📄 使用者開啟報表（新分頁）');\r\n    };\r\n    if (!isManual) {\r\n        $id('file-dl-html').href = htmlUrl;\r\n        $id('file-dl-html').onclick = () => slog('⬇ 使用者下載報表 HTML (result.html)');\r\n        $id('file-dl-json').href = jsonUrl;\r\n        $id('file-dl-json').onclick = () => slog('⬇ 使用者下載 result.json');\r\n    }\r\n\r\n    const rc = $id(`${scanTab}-result-card`);\r\n    rc.style.display = 'block';\r\n    rc.scrollIntoView({ behavior: 'smooth' });\r\n\r\n    // Reset UI\r\n    document.querySelectorAll('.tab-btn').forEach(b => b.disabled = false);\r\n    scanBtn.disabled = false;\r\n    cancelBtn.style.display = 'none';\r\n    scanStatus.textContent = cancelled ? '已取消' : '掃描完成';\r\n    abortController = null;\r\n});\r\n\r\ncancelBtn.addEventListener('click', () => {\r\n    if (abortController) {\r\n        abortController.abort();\r\n        cancelBtn.disabled = true;\r\n        scanStatus.textContent = '取消中…';\r\n    }\r\n});\r\n\r\n// Show findSW.ps1 download hint only in proxy mode (injection runs before DOMContentLoaded)\r\nwindow.addEventListener('DOMContentLoaded', () => {\r\n    if (window.__NVD_PROXY__) {\r\n        document.getElementById('findsw-dl-hint').style.display = 'block';\r\n    }\r\n});\r\n</script>\r\n</body>\r\n</html>\r\n",
  "config": {
    "portableEnable": true,
    "whitelist": "Microsoft,Apple,Google",
    "portables": [
      {
        "name": "putty",
        "version": "0.73"
      },
      {
        "name": "Apache Maven",
        "version": "3.8.6"
      },
      {
        "name": "Node.js",
        "version": "24.15.0"
      },
      {
        "name": "Neo4j Community Edition",
        "version": "2025.05.0"
      }
    ],
    "requestDelay": 700
  }
};
